using RaceDay.Web.Services; var builder=WebApplication.CreateBuilder(args);builder.Services.AddControllersWithViews();builder.Services.AddHttpContextAccessor();builder.Services.AddDistributedMemoryCache();builder.Services.AddSession(o=>{o.Cookie.HttpOnly=true;o.Cookie.IsEssential=true;o.IdleTimeout=TimeSpan.FromHours(8);});builder.Services.AddHttpClient<ApiClient>((sp,c)=>{c.BaseAddress=new Uri(sp.GetRequiredService<IConfiguration>()["ApiBaseUrl"]??"http://localhost:5080/");});var app=builder.Build();app.UseExceptionHandler("/Home/Error");app.UseStaticFiles();app.UseRouting();app.UseSession();app.MapControllerRoute("default","{controller=Home}/{action=Index}/{id?}");app.Run();
